  if($path==='/api/logout'&&$method==='POST'){$this->auth->logout();$this->jsonResponse(['ok'=>true]);}
  if($path==='/api/anonymous/token'&&$method==='GET'){$time=time();$nonce=id();$payload=$time.'.'.$nonce;$this->jsonResponse(['token'=>$payload.'.'.hash_hmac('sha256',$payload,Config::secret())]);}
  if($path==='/api/anonymous'&&$method==='POST')$this->anonymous($this->body());
  if($path==='/admin'||$path==='/workspace'){
   header('Cache-Control: no-store');header('X-Robots-Tag: noindex, nofollow');header('Content-Type: text/html; charset=utf-8');$theme=(new PublicSite($this->store))->theme;
   echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>TED² · V6 Research Studio</title><link rel="stylesheet" href="/assets/site.css?v=6"><link rel="stylesheet" href="/assets/admin.css?v=6"><style>'.PublicSite::themeCss($theme).'</style><script defer src="/assets/admin.js?v=6"></script></head><body class="admin-body" data-theme="'.e($theme['preset']??'vintage').'"><a class="skip" href="#content">Skip to editor</a><div id="app"><p class="loading">Opening research studio…</p></div><div id="toast" role="status" hidden></div><dialog id="dialog"></dialog></body></html>';exit;
  }
