  if(preg_match('#^/media/([a-f0-9]{32})$#D',$path,$m)&&in_array($method,['GET','HEAD'],true)){$row=$this->store->db->one('SELECT * FROM uploads WHERE id=?',[$m[1]]);ensure($row!==null,404,'Upload not found.');$media=new Media($this->store);ensure($media->canAccess($row,$this->auth->current(false)),404,'Upload is unavailable.');Media::send($media->path($row),$row['mime'],$row['original_name'],true);}
